/// <summary>
/// Service class to process Rebates
/// </summary>

public class METALMSupplierVolumetricRebateProcessRebService
{
}

Method.Source:
    /// <summary>
    /// ALM Supplier Process Rebates
    /// </summary>
    /// <param name = "_header"></param>
    /// <returns></returns>
    public METALMSupplierVolumetricRebateRes processRebates(METALMSupplierVolumetricRebateReq _request)
    {
        //var rebProcessResponse = new METALMSupplierVolumetricRebateRes();
        //System.String                    serializedJson,deserializedJson;
        //str                               jsonHeader;
        //System.Xml.Linq.XNode   node;

        METALMSupplierVolumetricRebateHeader volumetricRebateHeader;
        str                                  resultStr;

        //Class that processes the Volumetric rebates
        METALMSupplierVolumetricRebateProcessClass processor = new METALMSupplierVolumetricRebateProcessClass();
        var response = new  METALMSupplierVolumetricRebateRes();

        str rebNumber = _request.parmNumber();

        try
        {
            //Check if the rebate number is there
            if(rebNumber)
            {   
                volumetricRebateHeader = METALMSupplierVolumetricRebateHeader::find(rebNumber);
                if(volumetricRebateHeader.RecId)
                {
                    resultStr = processor.processRebateNew(volumetricRebateHeader);
                    if(resultStr == '@MET:METAMEXResponseSuccess')
                    {
                        response.parmSuccess(true);
                        response.parmErrorMessage(resultStr);
                    }
                    else
                    {
                        response.parmSuccess(false);
                        response.parmErrorMessage(resultStr);
                    }
                }
                else
                {
                    response.parmSuccess(false);
                    response.parmErrorMessage('@MET:METNumberNotFound');
                }

            }
            else
            {
                response.parmSuccess(false);
                response.parmErrorMessage('@MET:METNumberNotFound');
            }
        }
        catch
        {
            System.Exception interopException = CLRInterop::getLastException();

            response.parmSuccess(false);
            response.parmErrorMessage(interopException.ToString());
        }

        return response;
    }
